 103→    } catch {
 104→      return { error: "This email is already on the waitlist for this zip code." };
 105→    }
 106→  }
 107→
 108→  if (intent === "delete") {
 109→    const id = String(formData.get("id"));
 110→    try {
 111→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
 112→      if (!existing) return { error: "Entry not found." };
 113→      await db.waitlistEntry.delete({ where: { id } });
 114→      return { success: true, action: "deleted" };
 115→    } catch {
 116→      return { error: "Failed to delete entry." };
 117→    }
 118→  }
 119→
 120→  if (intent === "update-status") {
 121→    const id = String(formData.get("id"));
 122→    const status = String(formData.get("status"));
 123→    try {
 124→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
 125→      if (!existing) return { error: "Entry not found." };
 126→      await db.waitlistEntry.update({ where: { id }, data: { status } });
 127→      return { success: true, action: "updated" };
 128→    } catch {
 129→      return { error: "Failed to update entry status." };
 130→    }
 131→  }
 132→
 133→  if (intent === "bulk-notify") {
 134→    const zipCode = String(formData.get("zipCode") || "")
 135→      .trim()
 136→      .toUpperCase();
 137→    if (!zipCode) return { error: "Zip code is required." };
 138→
 139→    const bulkNotifySub = await getShopSubscription(shop);
 140→    if (PLAN_LIMITS[bulkNotifySub.planTier].maxWaitlist < UNLIMITED) {
 141→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
 142→    }
 143→
 144→    const updated = await db.waitlistEntry.updateMany({
 145→      where: { shop, zipCode, status: "waiting" },
 146→      data: { status: "notified" },
 147→    });
 148→
 149→    return {
 150→      success: true,
 151→      action: "bulk-notify",
 152→      count: updated.count,
 153→      zipCode,
 154→    };
 155→  }
 156→
 157→  if (intent === "notify-zip") {
 158→    const zipCode = String(formData.get("zipCode") || "").trim().toUpperCase();
 159→    if (!zipCode) return { error: "No ZIP code specified." };
 160→
 161→    const notifyZipSub = await getShopSubscription(shop);
 162→    if (PLAN_LIMITS[notifyZipSub.planTier].maxWaitlist < UNLIMITED) {
 163→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
 164→    }
 165→
 166→    const entries = await db.waitlistEntry.findMany({
 167→      where: { shop, zipCode, status: "waiting" },
 168→      select: { id: true, email: true },
 169→    });
 170→
 171→    if (entries.length === 0) {
 172→      return { action: "notify-zip", zipCode, emails: [] as string[], count: 0 };
 173→    }
 174→
 175→    await db.waitlistEntry.updateMany({
 176→      where: { shop, zipCode, status: "waiting" },
 177→      data: { status: "notified" },
 178→    });
 179→
 180→    const emails = entries.map((e) => e.email);
 181→    return { action: "notify-zip", zipCode, emails, count: emails.length };
 182→  }
 183→
 184→  if (intent === "notify-all") {
 185→    const notifyAllSub = await getShopSubscription(shop);
 186→    if (PLAN_LIMITS[notifyAllSub.planTier].maxWaitlist < UNLIMITED) {
 187→      return { error: "Notify All is only available on Pro or Ultimate plans. Please upgrade." };
 188→    }
 189→
 190→    const allWaiting = await db.waitlistEntry.findMany({
 191→      where: { shop, status: "waiting" },
 192→      select: { id: true, email: true, zipCode: true },
 193→    });
 194→
 195→    if (allWaiting.length === 0) {
 196→      return { action: "notify-all", emails: [] as string[], count: 0, zipBreakdown: [] as { zipCode: string; count: number }[] };
 197→    }
 198→
 199→    await db.waitlistEntry.updateMany({
 200→      where: { shop, status: "waiting" },
 201→      data: { status: "notified" },
 202→    });
 203→
 204→    const zipMap = new Map<string, number>();
 205→    for (const entry of allWaiting) {
 206→      zipMap.set(entry.zipCode, (zipMap.get(entry.zipCode) ?? 0) + 1);
 207→    }
 208→    const zipBreakdown = Array.from(zipMap.entries()).map(([zipCode, count]) => ({ zipCode, count }));
 209→    const emails = allWaiting.map((e) => e.email);
 210→
 211→    return { action: "notify-all", emails, count: emails.length, zipBreakdown };
 212→  }
 213→
 214→  if (intent === "delete-all-notified") {
 215→    const deleted = await db.waitlistEntry.deleteMany({
 216→      where: { shop, status: "notified" },
 217→    });
 218→    return { success: true, action: "deleted-notified", count: deleted.count };
 219→  }
 220→
 221→  if (intent === "accept") {
 222→    const id = String(formData.get("id"));
 223→    const entry = await db.waitlistEntry.findUnique({ where: { id } });
 224→    if (!entry || entry.shop !== shop) {
 225→      return { error: "Entry not found." };
 226→    }
 227→
 228→    // Add the ZIP code to the allowed list
 229→    await db.zipCode.upsert({
 230→      where: { shop_zipCode: { shop, zipCode: entry.zipCode } },
 231→      create: {
 232→        shop,
 233→        zipCode: entry.zipCode,
 234→        type: "allowed",
 235→        isActive: true,
 236→        label: `Requested by ${entry.name || entry.email}`,
 237→      },
 238→      update: {
 239→        type: "allowed",
 240→        isActive: true,
 241→      },
 242→    });
 243→
 244→    // Mark the waitlist entry as accepted
 245→    await db.waitlistEntry.update({
 246→      where: { id },
 247→      data: { status: "accepted" },
 248→    });
 249→
 250→    return { success: true, action: "accepted", zipCode: entry.zipCode };
 251→  }
 252→
 253→  if (intent === "reject") {
 254→    const id = String(formData.get("id"));
 255→    try {
 256→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
 257→      if (!existing) return { error: "Entry not found." };
 258→      await db.waitlistEntry.update({
 259→        where: { id },
 260→        data: { status: "rejected" },
 261→      });
 262→      return { success: true, action: "rejected" };
 263→    } catch {
 264→      return { error: "Failed to reject entry." };
 265→    }
 266→  }
 267→
 268→  return null;
 269→};
