 655→    >
 656→      <Box paddingBlockEnd="1600">
 657→      <Layout>
 658→        {/* Stats */}
 659→        <Layout.Section>
 660→          <InlineGrid columns={{ xs: 2, sm: 2, md: 5 }} gap="400">
 661→            <Box
 662→              padding="400"
 663→              background="bg-surface"
 664→              borderWidth="025"
 665→              borderColor="border"
 666→              borderRadius="200"
 667→            >
 668→              <BlockStack gap="100">
 669→                <Text as="p" tone="subdued" variant="bodySm">
