 676→            </Box>
 677→            <Box
 678→              padding="400"
 679→              background="bg-surface-warning"
 680→              borderWidth="025"
 681→              borderColor="border-warning"
 682→              borderRadius="200"
 683→            >
 684→              <BlockStack gap="100">
 685→                <Text as="p" tone="caution" variant="bodySm">
 686→                  Waiting
 687→                </Text>
 688→                <Text as="p" variant="headingXl" fontWeight="bold" tone="caution">
 689→                  {stats.waiting}
 690→                </Text>
 691→              </BlockStack>
 692→            </Box>
 693→            <Box
 694→              padding="400"
 695→              background="bg-surface-info"
 696→              borderWidth="025"
 697→              borderColor="border-info"
 698→              borderRadius="200"
 699→            >
 700→              <BlockStack gap="100">
 701→                <Text as="p" tone="subdued" variant="bodySm">
